    .proxy p { color: var(--text-secondary); font-size: 16px; line-height: 1.36; margin-top: 8px; }
    .footer {
      position: absolute;
      left: 88px;
      right: 88px;
      bottom: 38px;
      display: flex;
      justify-content: space-between;
      gap: 32px;
      color: var(--text-secondary);
      font-size: 14px;
      border-top: 1px solid rgba(91,42,29,.22);
      padding-top: 18px;
    }
    .footer strong { color: var(--text); }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
    .animate { animation: fadeInUp .7s ease both; }
    .delay-1 { animation-delay: .08s; } .delay-2 { animation-delay: .16s; } .delay-3 { animation-delay: .24s; } .delay-4 { animation-delay: .32s; }
    @media print { .viz-menu, .skip-link, .skip-to-content { display: none; } body { print-color-adjust: exact; -webkit-print-color-adjust: exact; } }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-link">Skip to content</a>
  <div class="viz-menu" aria-label="Visualization controls">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/></svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">☀️</span><span id="themeLabel">Light</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>
  <a href="#main-content" class="skip-to-content">Skip to content</a>
  <main id="main-content" class="poster" role="main">
    <section class="poster-header animate" aria-labelledby="poster-title">
      <div>
        <div class="kicker">1,500 years of written output</div>
        <h1 id="poster-title">The History of Books: From Manuscripts to Mass Production</h1>
        <p class="subtitle">For ten centuries books trickled from scriptoria and universities. After Gutenberg, production stops behaving like craft and starts behaving like infrastructure.</p>
      </div>
      <aside class="definition-card" aria-label="UNESCO book definition">
        <div class="label">UNESCO standard</div>
        <div class="value">Book = &gt;49 pages</div>
        <p>Modern title counts use a published work definition, linking today’s publishing data to long-run historical estimates.</p>
      </aside>
    </section>

    <section class="metrics-grid animate delay-1" aria-label="Key metrics">
      <article class="metric primary"><div class="num">~1440</div><div class="txt">Gutenberg’s printing press turns scarcity into reproducibility.</div></article>
      <article class="metric"><div class="num">10 centuries</div><div class="txt">Manuscript-era evidence spans the 6th through 15th centuries.</div></article>
      <article class="metric"><div class="num">1500–2009</div><div class="txt">Printed-book and title-per-capita data track the modern expansion.</div></article>
      <article class="metric"><div class="num">Proxy data</div><div class="txt">Book output reflects literacy, wealth, schooling, religion, and culture.</div></article>
    </section>

    <section class="main-chart-section animate delay-2" aria-labelledby="arc-title">
      <article class="chart-card">
        <div class="chart-title-row">
          <div>
            <h2 id="arc-title">The long arc: centuries of scarcity, then explosive print growth</h2>
            <p>Indexed European output, log scale. The visual gap is the point: manuscript growth was real but slow; print created a new order of magnitude.</p>
          </div>
          <div class="legend-note"><span><i class="dot manuscript"></i>Manuscripts</span><span><i class="dot print"></i>Printed books</span></div>
        </div>
        <div class="gutenberg-callout" aria-hidden="true"><div class="year">~1440</div><div class="caption">Moveable type compresses copying time and crashes the cost of reproduction.</div></div>
        <div class="chart-wrap" role="img" aria-label="Indexed book production from the sixth century to 2009 showing slow manuscript growth and sharp printed book acceleration after Gutenberg">
          <canvas id="arcChart" role="img" aria-label="Log-scale area and line chart of manuscript and printed book output index over time"></canvas>
        </div>
        <p class="sr-only">The manuscript index rises slowly from 1 in year 550 to 75 around 1450. Printed output rises from 120 in 1500 to 120000 in 2009 on a log scale.</p>
      </article>
      <aside class="side-stack" aria-label="Era notes">
        <article class="side-card"><div class="era">Manuscript era</div><h3>Books as luxury goods</h3><p>Hand copying made books slow, scarce, and expensive — concentrated in monasteries, courts, and elite universities.</p><div class="big">6th–15th</div></article>
        <article class="side-card"><div class="era">Print revolution</div><h3>Reproduction becomes scalable</h3><p>Presses spread across Western Europe, multiplying titles and lowering the price of access to ideas.</p><div class="big">1500+</div></article>
        <article class="side-card"><div class="era">Mass production</div><h3>Books become infrastructure</h3><p>Industrial printing and global education systems turn publishing into a mature mass cultural industry.</p><div class="big">1800–today</div></article>
      </aside>
    </section>

    <section class="lower-section animate delay-3" aria-label="Modern publishing and timeline">
      <article class="compact-card" aria-labelledby="country-title">
        <header>
          <div><h2 id="country-title">Modern publishing remains uneven</h2><p>New titles per million people vary widely by country, reflecting education systems, income, language markets, and publishing institutions.</p></div>
        </header>
        <div class="small-chart-wrap" role="img" aria-label="Country comparison of new book titles per million people in 2009">
          <canvas id="countryChart" role="img" aria-label="Horizontal bar chart showing selected countries by new book titles per million people"></canvas>
        </div>
      </article>
      <article class="compact-card timeline-card" aria-labelledby="timeline-title">
        <header><div><h2 id="timeline-title">Five turning points</h2><p>The shift from handwritten scarcity to industrial abundance is a sequence of social and technical accelerations.</p></div></header>
        <div class="timeline" aria-label="Historical milestones">
          <div class="milestone"><div class="date">800s</div><div class="title">Carolingian revival</div><div class="desc">Scriptoria and standard scripts boost written output.</div></div>
          <div class="milestone"><div class="date">1200s</div><div class="title">Universities rise</div><div class="desc">Scholastic demand expands manuscript markets.</div></div>
          <div class="milestone"><div class="date">1440</div><div class="title">Gutenberg press</div><div class="desc">Moveable type changes the economics of copying.</div></div>
          <div class="milestone"><div class="date">1700s</div><div class="title">Enlightenment</div><div class="desc">Print networks circulate science, politics, and reform.</div></div>
          <div class="milestone"><div class="date">1800s</div><div class="title">Industrial print</div><div class="desc">Steam power, paper, and schooling create mass readership.</div></div>
        </div>
      </article>
    </section>

    <section class="mirror-section animate delay-4" aria-labelledby="mirror-title">
      <article class="mirror-card lede">
        <h2 id="mirror-title">Books as a mirror of society</h2>
        <p>When books multiply, they reveal more than publishing capacity. They mark societies becoming more literate, more urban, richer, and more connected.</p>
      </article>
      <article class="mirror-card" aria-label="Social signals reflected by book production">
        <div class="proxy-grid">
          <div class="proxy"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M4 4v15.5A2.5 2.5 0 0 1 6.5 17H20V4z"/></svg><h3>Literacy</h3><p>More readers create demand; more books support reading.</p></div>
          <div class="proxy"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 1v22"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7H14a3.5 3.5 0 0 1 0 7H6"/></svg><h3>Wealth</h3><p>Falling prices make books shift from luxury to commodity.</p></div>
          <div class="proxy"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 10 12 5 2 10l10 5z"/><path d="M6 12v5c3 2 9 2 12 0v-5"/></svg><h3>Education</h3><p>Schools and universities become engines of title growth.</p></div>
          <div class="proxy"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="m4.9 4.9 14.2 14.2"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg><h3>Culture</h3><p>Religious dominance gives way to wider secular output.</p></div>
        </div>
      </article>
    </section>

    <footer class="footer"><span><strong>Sources:</strong> Buringh & Van Zanden (2009), Fink-Jensen (2015), Roser & Ritchie (2023), Our World in Data.</span><span>Designed as an A1 portrait data-report poster · Values are indexed/selected to communicate long-run magnitude.</span></footer>
  </main>
  <script src="/app/libs/html-to-image.js"></script>
  <script>
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart initialization failed for ' + canvasId, error); return null; }
      }
    };
    var chartsBuilt = false;
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'light';
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    function cssVar(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
    function rgba(hex, alpha) {
      var h = hex.replace('#','');
      var r = parseInt(h.substring(0,2),16), g = parseInt(h.substring(2,4),16), b = parseInt(h.substring(4,6),16);
      return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }
    var arcLabels = ['550','800','1000','1200','1350','1450','1500','1550','1650','1750','1850','1950','2009'];
    var manuscriptData = [1, 3, 5, 14, 34, 75, null, null, null, null, null, null, null];
    var printData = [null, null, null, null, null, null, 120, 520, 1800, 5600, 18500, 62000, 120000];
    var countryLabels = ['United Kingdom','Iceland','Denmark','Netherlands','United States','Germany','Spain','Japan','Brazil'];
    var countryData = [2875, 2628, 2414, 1950, 959, 1142, 1018, 610, 246];
    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var text = cssVar('--text');
      var muted = cssVar('--text-secondary');
      var accent = cssVar('--accent');
      var brown = '#7d6040';
      ChartManager.safeInit('arcChart', {
        type: 'line',
        data: { labels: arcLabels, datasets: [
          { label: 'Manuscripts (indexed)', data: manuscriptData, borderColor: brown, backgroundColor: 'rgba(125,96,64,0.18)', fill: true, tension: 0.35, pointRadius: 5, pointHoverRadius: 7, borderWidth: 4, spanGaps: false },
          { label: 'Printed books (indexed)', data: printData, borderColor: accent, backgroundColor: rgba(accent, .22), fill: true, tension: 0.30, pointRadius: 5, pointHoverRadius: 7, borderWidth: 5, spanGaps: false }
        ]},
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 30, right: 28, bottom: 12, left: 16 } },
          plugins: { legend: { display: false }, tooltip: { enabled: true, callbacks: { label: function(c) { return c.dataset.label + ': ' + c.parsed.y.toLocaleString() + '× index'; } } } },
          scales: {
            y: { type: 'logarithmic', min: 1, max: 150000, title: { display: true, text: 'Output index (log scale)', color: muted, font: { size: 17, weight: 'bold' } }, ticks: { color: muted, font: { size: 14 }, callback: function(v) { return [1,10,100,1000,10000,100000].indexOf(v) >= 0 ? v.toLocaleString() : ''; } }, grid: { color: 'rgba(91,42,29,0.06)' } },
            x: { ticks: { color: text, font: { size: 15, weight: 'bold' }, maxRotation: 0 }, grid: { color: 'rgba(91,42,29,0.045)' } }
          }
        }
      });
      ChartManager.safeInit('countryChart', {
        type: 'bar',
        data: { labels: countryLabels, datasets: [{ label: 'New titles per million people', data: countryData, backgroundColor: countryData.map(function(v, i) { return i < 3 ? rgba(accent, .88) : 'rgba(91,42,29,.58)'; }), borderColor: countryData.map(function(v, i) { return i < 3 ? accent : 'rgba(91,42,29,.78)'; }), borderWidth: 1, borderRadius: 6 }] },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 8, right: 34, bottom: 8, left: 8 } },
          plugins: { legend: { display: false }, tooltip: { enabled: true, callbacks: { label: function(c) { return c.parsed.x.toLocaleString() + ' titles per million people'; } } } },
          scales: {
            x: { beginAtZero: true, ticks: { color: muted, font: { size: 13 }, callback: function(v) { return v.toLocaleString(); } }, grid: { color: 'rgba(91,42,29,0.055)' } },
            y: { ticks: { color: text, font: { size: 15, weight: 'bold' } }, grid: { display: false } }
          }
        }
      });
      chartsBuilt = true;
    }
    function onThemeChange() { if (chartsBuilt) buildCharts(); }
    function downloadImage() {
      var node = document.getElementById('main-content');
      if (typeof htmlToImage === 'undefined') { console.error('html-to-image not loaded'); return; }
      htmlToImage.toPng(node, { pixelRatio: 1, backgroundColor: cssVar('--bg') }).then(function(dataUrl) {
        var link = document.createElement('a');
        link.download = 'history-of-books-poster.png';
        link.href = dataUrl;
        link.click();
      });
    }
    applyTheme('light');
    buildCharts();
  </script>
</body>
